import pandas as pd


def run(inputs: dict) -> dict:
    invoices = inputs["invoices"].copy()
    payments = inputs["payments"].copy()

    # Original invoice amounts (for OPEN/PARTIAL/PAID determination)
    orig_amount = invoices.set_index("invoice_id")["amount"].astype(float).to_dict()

    # Mutable open-amount state per invoice
    inv_open = dict(orig_amount)

    # Build per-customer ordered invoice lists: oldest due_date first, then invoice_id
    invoices_sorted = invoices.sort_values(["customer_id", "due_date", "invoice_id"])
    cust_invoices = (
        invoices_sorted.groupby("customer_id")["invoice_id"]
        .apply(list)
        .to_dict()
    )

    # Order payments per customer by paid_ts then payment_id (cursor order)
    payments_sorted = payments.sort_values(["customer_id", "paid_ts", "payment_id"])

    allocations = []
    credit = {}

    for row in payments_sorted.itertuples(index=False):
        cust = row.customer_id
        left = float(row.amount)
        pay_id = row.payment_id

        inv_list = cust_invoices.get(cust, [])

        if left > 0:
            for inv_id in inv_list:
                if left <= 0:
                    break
                open_amt = inv_open.get(inv_id, 0.0)
                if open_amt <= 0:
                    continue
                pay = left if left < open_amt else open_amt
                inv_open[inv_id] = open_amt - pay
                left -= pay
                allocations.append((pay_id, inv_id, pay))
                if left == 0:
                    break

        if left > 0:
            credit[cust] = credit.get(cust, 0.0) + left

    # Build invoice_status preserving original invoice order
    status_rows = []
    for inv_id in invoices["invoice_id"]:
        orig = orig_amount[inv_id]
        open_amt = inv_open[inv_id]
        if open_amt == orig:
            status = "OPEN"
        elif open_amt == 0:
            status = "PAID"
        else:
            status = "PARTIAL"
        status_rows.append((inv_id, open_amt, status))

    invoice_status = pd.DataFrame(
        status_rows, columns=["invoice_id", "open_amount", "status"]
    )
    if not invoice_status.empty:
        invoice_status["invoice_id"] = invoice_status["invoice_id"].astype("int64")
        invoice_status["open_amount"] = invoice_status["open_amount"].astype("float64")
        invoice_status["status"] = invoice_status["status"].astype(object)
    else:
        invoice_status = pd.DataFrame(
            columns=["invoice_id", "open_amount", "status"]
        ).astype({"invoice_id": "int64", "open_amount": "float64", "status": object})

    allocations_df = pd.DataFrame(
        allocations, columns=["payment_id", "invoice_id", "applied_amount"]
    )
    if not allocations_df.empty:
        allocations_df["payment_id"] = allocations_df["payment_id"].astype("int64")
        allocations_df["invoice_id"] = allocations_df["invoice_id"].astype("int64")
        allocations_df["applied_amount"] = allocations_df["applied_amount"].astype("float64")
    else:
        allocations_df = pd.DataFrame(
            columns=["payment_id", "invoice_id", "applied_amount"]
        ).astype({"payment_id": "int64", "invoice_id": "int64", "applied_amount": "float64"})

    credit_rows = [(c, amt) for c, amt in credit.items() if amt > 0]
    customer_credit = pd.DataFrame(
        credit_rows, columns=["customer_id", "unapplied_amount"]
    )
    if not customer_credit.empty:
        customer_credit["customer_id"] = customer_credit["customer_id"].astype("int64")
        customer_credit["unapplied_amount"] = customer_credit["unapplied_amount"].astype(
            "float64"
        )
    else:
        customer_credit = pd.DataFrame(
            columns=["customer_id", "unapplied_amount"]
        ).astype({"customer_id": "int64", "unapplied_amount": "float64"})

    return {
        "invoice_status": invoice_status,
        "allocations": allocations_df,
        "customer_credit": customer_credit,
    }
